import json,re,shutil
from pathlib import Path
from pypdf import PdfReader

out=Path('dist'); out.mkdir(exist_ok=True)
shutil.copyfile(r'C:/Users/kunal/Downloads/Math_285_Notes_1_5.pdf',out/'textbook.pdf')
shutil.copyfile(r'C:/Users/kunal/Downloads/Calendar Fa2026.txt',out/'calendar.txt')
shutil.copytree('node_modules/katex/dist',out/'katex',dirs_exist_ok=True)
pages=[p.extract_text() for p in PdfReader(out/'textbook.pdf').pages]
exercises={}
for i,text in enumerate(pages):
    if i<18 or i>=192: continue
    for match in re.finditer(r'Exercise\s*(\d+\.\d+\.\d+)',text):
        exercises.setdefault(match[1],i+1)
sections={}
def section(key,title,page,goals,formula,trap):
    sections[key]=dict(id=key,title=title,page=page,goals=goals,formula=formula,trap=trap,problems=[])
def problem(key,ref,page,title,prompt,hints,steps,answer,check):
    sections[key]['problems'].append(dict(id=f'{key}-{len(sections[key]["problems"])+1}',ref=ref,page=page,title=title,prompt=prompt,hints=hints,steps=steps,answer=answer,check=check))

section('1.1','What is a differential equation?',19,['Classify order and linearity','Verify a proposed solution and its initial data'],r'L[y]=f(t)', 'Linearity concerns y and its derivatives, not the independent variable.')
problem('1.1','Exercise 1.1.2',24,'Classify an equation',r'Give an example of a third-order linear ODE and explain its classification.', ['Use y and its derivatives only to the first power.'],[r'Choose \(y^{(3)}+t^2y\prime+\sin(t)y=e^t\).', 'The highest derivative is the third derivative. All coefficients depend only on t.'],r'\text{Order 3; linear, inhomogeneous.}', 'A product such as yy′ would make it nonlinear.')
problem('1.1','Exercise 1.1.3',24,'Verify by substitution',r'Check that \(y=1-t^2\) solves \(ty\prime-y=-(1+t^2)\).',['Differentiate first; then substitute both y and y′.'],[r'\(y\prime=-2t\).',r'\(ty\prime-y=t(-2t)-(1-t^2)=-1-t^2\).'],r'\text{Yes, for all real }t.', 'The left and right sides agree identically.')
problem('1.1','Exercise 1.1.4',24,'A cycle of derivatives',r'If \(y\prime\prime+y=0\), \(y(0)=1\), \(y\prime(0)=0\), find \(y^{(k)}(0)\).',['The derivatives repeat every four steps.'],[r'From the ODE, \(y^{(k+2)}=-y^{(k)}\).', 'The values start 1, 0, −1, 0, and repeat.'],r'y^{(k)}(0)=\cos(k\pi/2)', 'The formula gives 1 at k=0 and 0 at k=1.')
section('1.2','Integration and separation',24,['Separate variables','Keep equilibria and find the IVP interval'],r'\int \frac{dy}{g(y)}=\int f(t)\,dt','Dividing by a function of y can discard constant solutions.')
problem('1.2','Exercise 1.2.1',28,'A logarithmic substitution',r'Solve \(y\prime=ty\ln|y|\).',['For y≠0 set u=ln|y|.'],[r'\(u\prime=y\prime/y=tu\), so \(u=Ce^{t^2/2}\).',r'Exponentiate and choose the sign of y on its interval.'],r'y(t)=\pm\exp(Ce^{t^2/2})', 'C=0 includes y=±1. The original RHS is undefined at y=0.')
problem('1.2','Exercises 1.2.2–1.2.3',28,'Projectile motion',r'A projectile starts at ground level with vertical speed 100 m/s, horizontal speed 20 m/s, and gravity 10 m/s². Find flight time and range.',['Integrate vertical acceleration twice.'],[r'\(v(t)=100-10t\); height \(h(t)=100t-5t^2\).',r'The positive root of \(h(t)=0\) is t=20. Horizontal distance is 20t.'],r't=20\text{ s},\qquad R=400\text{ m}', 'At 20 seconds height is 0; air resistance is omitted as in the exercise.')
problem('1.2','Exercise 1.2.4(f)',28,'A separable IVP',r'Solve \(y\prime=(1+\cos t)y\), \(y(0)=2\).',['Separate dy/y from dt.'],[r'\(\ln|y|=t+\sin t+C\).',r'\(y=Ae^{t+\sin t}\); initial data gives A=2.'],r'y=2e^{t+\sin t}', 'Differentiation gives y′=(1+cos t)y; y(0)=2.')
problem('1.2','Exercise 1.2.4(h)',28,'Finite-time blow-up',r'Solve \(y\prime=y^2/(t+1)\), \(y(0)=2\), and give its maximal interval.',['Integrate y⁻² and locate both types of singularities.'],[r'\(-1/y=\ln|t+1|+C\), with C=−1/2.',r'On the interval containing 0, t>−1. The denominator vanishes when ln(t+1)=1/2.'],r'y=\frac{1}{1/2-\ln(t+1)},\quad -1<t<\sqrt e-1', 'The interval must contain the initial point and stop at the first singularities.')
section('1.3','Slope fields',29,['Read the sign of a slope','Connect geometry with solution curves'],r'y\prime=f(t,y)', 'A vertical tangent can occur at a point where the explicit ODE is undefined.')
problem('1.3','Supplemental • based on Example 1.3.1',29,'Circles in a slope field',r'For \(y\prime=-t/y\), identify the solution through (0,2), its interval, and the slope at (1,1).',['Integrate ydy=−tdt.'],[r'\(y^2+t^2=C\); (0,2) gives C=4.',r'The positive branch is chosen by the initial data. It stops where y=0.',r'At (1,1), the field slope is −1.'],r'y=\sqrt{4-t^2},\quad -2<t<2', 'The point (1,1) is a field point, not on this particular circle.')
section('1.4','Existence and uniqueness',31,['Check continuity near the initial point','Separate failure of a theorem from nonexistence'],r'f,\ f_y\text{ continuous near }(t_0,y_0)\Rightarrow\text{local uniqueness}', 'A failed hypothesis does not by itself prove that a solution is absent.')
problem('1.4','Exercise 1.4.1(a,b)',35,'A singular coefficient',r'Does the theorem guarantee a unique solution for \(y\prime=ty-y^2/t^2\), with y(0)=1 or y(3)=1?',['Inspect t=0 before differentiating with respect to y.'],[r'The RHS is undefined at t=0, so the stated ODE has no classical solution there.',r'Near (3,1), f and \(f_y=t-2y/t^2\) are continuous.'],r'\text{At }(0,1):\text{ no guarantee; at }(3,1):\text{ locally unique.}', 'The local theorem does not guarantee a solution for every real t.')
problem('1.4','Exercise 1.4.1(e)',35,'Existence without uniqueness',r'Analyze \(y\prime=y^{1/3}/t^2\), \(y(1)=0\).',['f is continuous near (1,0), but fy is unbounded.'],[r'Existence is guaranteed by continuity. The derivative in y is \(1/(3t^2y^{2/3})\), undefined at y=0.',r'One solution is zero. Another for t≥1 is \([\frac23(1-1/t)]^{3/2}\), joined to zero for 0<t≤1. Both are differentiable at 1.'],r'\text{Existence yes; uniqueness no.}', 'The two solutions share the same initial value and satisfy the equation on a neighborhood of 1.')
section('1.5','First-order linear equations',35,['Use an integrating factor','Model mixing with variable volume'],r'\mu=e^{\int p(t)dt},\qquad(\mu y)\prime=\mu q','Put the equation in standard form before choosing μ.')
problem('1.5','Exercise 1.5.2(a)',39,'Integrating factor IVP',r'Solve \(y\prime+2y=1+t\), \(y(0)=0\).',['Multiply by e²ᵗ.'],[r'\((e^{2t}y)\prime=(1+t)e^{2t}\).',r'Integration gives \(y=t/2+1/4+Ce^{-2t}\). The initial condition sets C=−1/4.'],r'y=\frac t2+\frac14-\frac14e^{-2t}', 'y′+2y=t+1 and y(0)=0.')
problem('1.5','Exercise 1.5.2(d)',39,'Recognize a product derivative',r'Solve \(y\prime+\frac{2t}{1+t^2}y=\frac{\cos t}{1+t^2}\), y(0)=1.',['The integrating factor is 1+t².'],[r'\(((1+t^2)y)\prime=\cos t\).',r'\((1+t^2)y=\sin t+C\); C=1.'],r'y=\frac{1+\sin t}{1+t^2}', 'The denominator never vanishes on the real line.')
problem('1.5','Exercise 1.5.1',39,'A tank with increasing volume',r'Initially 10 kg salt in 100 L. Inflow: 10 L/min at 0.001 kg/L. Outflow: 5 L/min. Find salt mass Y(t) and when it is minimal (assume unlimited tank capacity).',['Volume is 100+5t; salt-out rate is 5Y/(100+5t).','Use μ=t+20.'],[r'\(Y\prime=0.01-Y/(t+20)\).',r'\(((t+20)Y)\prime=0.01(t+20)\). Integrate and use Y(0)=10.',r'\(Y=0.005(t+20)+198/(t+20)\). Set Y′=0 to obtain (t+20)²=39600.'],r'Y=0.005(t+20)+\frac{198}{t+20},\quad t_{\min}=\sqrt{39600}-20\approx179.0\text{ min}', 'Y″=396/(t+20)³>0 for t≥0, confirming a minimum.')
section('1.6','Exact equations and substitutions',40,['Test exactness','Use Bernoulli, homogeneous, and order reduction substitutions'],r'M_y=N_t,\quad\psi_t=M,\quad\psi_y=N,\quad\psi=C', 'Keep lost equilibria when dividing; substitutions may restrict the domain.')
problem('1.6','Supplemental • exactness practice',40,'Find a potential',r'Solve \((2t+y)+(t+2y)y\prime=0\), \(y(0)=1\).',['Integrate M with respect to t and match ψy to N.'],[r'\(M_y=N_t=1\), so the equation is exact.',r'\(\psi=t^2+ty+g(y)\). Matching ψy=t+2y gives g=y².',r'The initial point fixes C=1.'],r't^2+ty+y^2=1', 'Differentiating this relation recovers the ODE wherever t+2y≠0.')
problem('1.6','Exercise 1.6.6(a)',47,'Bernoulli transformation',r'Solve \(y\prime+y=t/y\).',['Multiply by 2y and set w=y².'],[r'\(w\prime+2w=2t\).',r'An integrating factor gives \(w=t-1/2+Ce^{-2t}\).'],r'y=\pm\sqrt{t-1/2+Ce^{-2t}}', 'Use an interval with positive radicand. y=0 is not allowed in this original equation.')
problem('1.6','Exercise 1.6.5(c)',46,'Reduce the order',r'Find the general solution of \(ty\prime\prime=y\prime\).',['Let v=y′.'],[r'For t≠0, \(v\prime=v/t\), hence v=At.',r'Integrate again to obtain a quadratic plus a constant.'],r'y=C_1t^2+C_2', 'These polynomials also satisfy the undivided equation at t=0.')
problem('1.6','Exercise 1.6.7(d)',47,'A nonlinear IVP',r'Solve \((t+1)y\prime=y^2\), y(0)=1.',['Separate variables and find the singularity of the solution.'],[r'\(-1/y=\ln(t+1)-1\) near t=0.',r'The right endpoint occurs at ln(t+1)=1.'],r'y=\frac{1}{1-\ln(t+1)},\quad -1<t<e-1', 'Direct substitution verifies the equation and initial value.')
section('1.7','Autonomous equations and phase lines',48,['Find equilibria and sign intervals','Classify stability and bifurcations'],r'y\prime=f(y),\quad f(y_*)=0','A zero derivative f′(y*) requires a sign analysis; the linear test is inconclusive.')
problem('1.7','Supplemental • based on Example 1.7.1',48,'Read a phase line',r'For \(y\prime=y^2-1\), classify equilibria and find the limit of the solution starting at y(0)=0.',['Factor (y−1)(y+1) and test three intervals.'],[r'The sign is positive below −1, negative between −1 and 1, positive above 1.',r'Trajectories move toward −1 and away from 1. Starting at 0, the solution decreases toward −1.'],r'y_*=-1\text{ stable};\quad y_*=1\text{ unstable};\quad \lim_{t\to\infty}y(t)=-1', 'The explicit IVP solution is −tanh(t).')
problem('1.7','Supplemental • based on harvesting model',52,'Sustainable harvesting',r'For \(P\prime=P(10-P)-h\), find the critical harvest and equilibria when h=16.',['Complete the square in P.'],[r'\(P(10-P)-h=25-h-(P-5)^2\).',r'At h=16, roots are 2 and 8. f′=10−2P gives unstable at 2 and stable at 8.',r'At h=25 the equilibria merge at 5; above 25 there are none.'],r'h_c=25,\qquad P_*=2\ (\text{unstable}),\ 8\ (\text{stable})', 'At critical harvest 5 is semistable; below the lower equilibrium the model predicts population collapse.')
section('1.8','Numerical methods',53,['Apply Euler and improved Euler','Distinguish step size from final time'],r'y_{n+1}=y_n+h f(t_n,y_n)','Euler uses the old point; Heun averages a predictor slope with the old slope.')
problem('1.8','Supplemental • based on §1.8',53,'Two Euler steps',r'Use h=0.1 to estimate y(0.2) for \(y\prime=y+t\), y(0)=1.',['Apply the update twice, including the time in f.'],[r'\(y_1=1+0.1(1+0)=1.1\).',r'\(y_2=1.1+0.1(1.1+0.1)=1.22\).',r'The exact solution is \(2e^t-t-1\), so at 0.2 it is about 1.24281.'],r'y(0.2)\approx1.22\quad\text{(Euler)}', 'The error is about −0.02281.')
problem('1.8','Supplemental • improved Euler',54,'Predict and correct',r'Use one Heun step of size 0.1 for \(y\prime=y+t\), y(0)=1.',['First predict with Euler, then average slopes.'],[r'Old slope is 1. Predictor is 1.1. New slope at (0.1,1.1) is 1.2.',r'Corrected value is \(1+0.1(1+1.2)/2\).'],r'y(0.1)\approx1.11', 'Exact value is about 1.11034, closer than Euler’s 1.1.')
section('2.1','Independence and the Wronskian',58,['Compute Wronskians','Choose a fundamental set'],r'W(y_1,y_2)=y_1y_2\prime-y_1\prime y_2', 'W≡0 is decisive for solutions of the same regular homogeneous linear ODE; arbitrary functions require care.')
problem('2.1','Exercise 2.1.1(a)',64,'A repeated-root pair',r'Are \(e^{3t}\) and \(te^{3t}\) independent?',['Calculate a 2×2 determinant.'],[r'\(W=e^{3t}(e^{3t}+3te^{3t})-3e^{3t}(te^{3t})\).',r'This simplifies to e⁶ᵗ, which never vanishes.'],r'W=e^{6t}\ne0;\quad\text{independent}', 'The extra t factor supplies the second solution for a repeated root.')
problem('2.1','Exercise 2.1.1(b)',64,'A redundant function',r'Are \(e^{3t},2e^{3t},te^{3t}\) independent?',['Look for a constant linear relation before expanding a determinant.'],[r'The second function is twice the first.',r'\(2e^{3t}-2e^{3t}+0\cdot te^{3t}=0\) gives a nontrivial coefficient relation (2,−1,0).'],r'W\equiv0;\quad\text{dependent}', 'Two proportional columns force the Wronskian determinant to vanish.')
section('2.2','Characteristic polynomials',64,['Handle real, complex, and repeated roots','Count independent solutions'],r'r=\alpha\pm i\beta\Rightarrow e^{\alpha t}(C_1\cos\beta t+C_2\sin\beta t)', 'For a root of multiplicity m include t⁰ through tᵐ⁻¹.')
for ref,prompt,steps,answer in [
('a',r'y\prime\prime+y\prime-6y=0',[r'Factor \(r^2+r-6=(r-2)(r+3)\).','Each distinct real root supplies an exponential.'],r'y=C_1e^{2t}+C_2e^{-3t}'),
('b',r'y^{(3)}-6y\prime\prime+9y\prime=0',[r'Factor \(r(r-3)^2\).','The root 0 gives a constant; the repeated root 3 gives e³ᵗ and te³ᵗ.'],r'y=C_1+(C_2+C_3t)e^{3t}'),
('e',r'y^{(4)}+2y\prime\prime+y=0',[r'\(r^4+2r^2+1=(r^2+1)^2\).','Both ±i have multiplicity 2.'],r'y=(C_1+C_2t)\cos t+(C_3+C_4t)\sin t')]:
    problem('2.2',f'Exercise 2.2.2({ref})',71,'Characteristic roots',f'Find the general solution of \\({prompt}\\).',['Try y=eʳᵗ and factor the resulting polynomial.'],steps,answer,'The number of arbitrary constants equals the order of the equation.')
section('2.3-2.4','Operators and inhomogeneous structure',71,['Write L[y]=f','Combine a particular solution with the homogeneous family'],r'y=y_p+y_h','The sum of two solutions of L[y]=f has forcing 2f, not f.')
problem('2.3-2.4','Supplemental • §§2.3–2.4',73,'Build the whole family',r'Given \(y_p=t\) for \(y\prime\prime+y=t\), find all solutions and impose y(0)=2, y′(0)=0.',['Add the kernel of D²+1.'],[r'\(y=t+A\cos t+B\sin t\).',r'The data give A=2 and 1+B=0.'],r'y=t+2\cos t-\sin t','Applying D²+1 cancels the trigonometric terms and leaves t.')
section('2.5','Undetermined coefficients',74,['Choose a forcing-compatible trial','Adjust for resonance'],r'y_p=t^s e^{\alpha t}P_m(t)\quad\text{with }s\text{ the root multiplicity}', 'Include both sine and cosine in a trigonometric trial.')
problem('2.5','Exercise 2.6.1(a) • shared practice set',81,'An exponential forcing',r'Find a particular solution of \(y\prime+y=e^t\).',['Try Aeᵗ.'],[r'\(y_p\prime+y_p=2Ae^t\). Matching coefficients gives A=1/2.'],r'y_p=\tfrac12e^t','Substitution yields exactly eᵗ. The general solution also contains Ce⁻ᵗ.')
problem('2.5','Exercise 2.6.4(g) • shared practice set',82,'Resonance with sine and cosine',r'Find a particular solution of \(y\prime\prime+y=4\cos t-6\sin t\).',['Multiply the usual sine/cosine trial by t.'],[r'Use \(y_p=t(A\cos t+B\sin t)\).',r'\((D^2+1)y_p=-2A\sin t+2B\cos t\). Hence A=3 and B=2.'],r'y_p=3t\cos t+2t\sin t','The factor t prevents overlap with the homogeneous solutions.')
section('2.6','Annihilators',78,['Construct annihilating operators','Use multiplicity to select a trial'],r'D^{m+1}P_m=0,\quad (D-\alpha)e^{\alpha t}=0','Applying an annihilator enlarges the solution space; match the original forcing afterward.')
problem('2.6','Exercise 2.6.2(a,b,d)',81,'Build three annihilators',r'Find annihilators for \(t^2+5t\), \(\sin3t\), and \(t^2e^t+\sin t\).',['Use a product for different forcing types.'],[r'A degree-2 polynomial is killed by D³.',r'\(\sin3t\) is killed by D²+9.',r'\(t^2e^t\) is killed by (D−1)³ and sin t by D²+1. Constant-coefficient factors commute.'],r'D^3;\qquad D^2+9;\qquad (D-1)^3(D^2+1)','These are valid minimal constant-coefficient annihilators for these functions.')
problem('2.6','Exercise 2.6.3(c)',82,'Choose the resonant trial',r'Give the correct trial for \(y\prime\prime+y=\sin t\), then find a particular solution.',['The roots ±i already occur in the homogeneous operator.'],[r'Trial: \(t(A\cos t+B\sin t)\).',r'The image under D²+1 is −2A sin t+2B cos t; take A=−1/2, B=0.'],r'y_p=-\tfrac12t\cos t','The forcing annihilator is D²+1; the enlarged operator has roots ±i of multiplicity 2.')
section('2.7','Variation of parameters',82,['Normalize the equation','Integrate using a fundamental pair'],r'u_1\prime=-y_2f/W,\quad u_2\prime=y_1f/W,\quad y_p=u_1y_1+u_2y_2', 'These formulas assume the leading coefficient is 1.')
problem('2.7','Supplemental • based on §2.7',82,'A nonstandard forcing',r'Solve \(y\prime\prime+y=\sec t\) on \((-\pi/2,\pi/2)\).',['Choose cos t and sin t; their Wronskian is 1.'],[r'\(u_1\prime=-\tan t\), so u₁=ln(cos t).',r'\(u_2\prime=1\), so u₂=t. Constants of integration are absorbed into yₕ.'],r'y=C_1\cos t+C_2\sin t+\cos t\ln(\cos t)+t\sin t','Differentiating twice gives y″+y=sec t on the stated interval.')
section('2.8','Laplace transforms',85,['Transform derivatives and initial data','Invert by decomposition and shifting'],r'\mathcal L\{y\prime\prime\}=s^2Y-sy(0)-y\prime(0)','A time shift requires writing the function in terms of t−a.')
problem('2.8','Exercise 2.8.1(a)',90,'Transform an IVP',r'Find Y(s) for \(y\prime+y=\sin t+6\), y(0)=2.',['L[y′]=sY−y(0).'],[r'\((s+1)Y-2=1/(s^2+1)+6/s\).','Isolate Y by dividing by s+1.'],r'Y(s)=\frac{2+1/(s^2+1)+6/s}{s+1}','The initial value is included before solving for Y.')
problem('2.8','Exercise 2.8.2(c,e)',91,'Two inverse transforms',r'Invert \(1/(s+3)^5\) and \((4s+3)/((s-2)^2+1)\).',['Rewrite 4s+3 as 4(s−2)+11.'],[r'Use \(\mathcal L[t^4]=24/s^5\) and an exponential shift.',r'The second transform splits into shifted cosine and sine transforms.'],r'\frac{t^4e^{-3t}}{24};\qquad e^{2t}(4\cos t+11\sin t)','The numerator shift is essential: the sine coefficient is 11, not 3.')
problem('2.8','Exercise 2.8.3(a)',91,'Laplace IVP solution',r'Solve \(y\prime\prime-4y\prime+3y=e^{2t}\), y(0)=1, y′(0)=2.',['Factor s²−4s+3.'],[r'\((s^2-4s+3)Y-s+2=1/(s-2)\).',r'\(Y=(s-2)/((s-1)(s-3))+1/((s-1)(s-2)(s-3))\).',r'Partial fractions give \(Y=1/(s-1)+1/(s-3)-1/(s-2)\).'],r'y=e^t+e^{3t}-e^{2t}','At 0, y=1 and y′=2; applying the operator to −e²ᵗ gives e²ᵗ.')
section('3.1.1','Undamped mechanical oscillations',93,['Find frequency and period','Solve forced undamped IVPs'],r'my\prime\prime+ky=0,\quad\omega_0=\sqrt{k/m}','Resonance in an undamped oscillator produces a growing envelope.')
problem('3.1.1','Exercise 3.1.8(a)',99,'Forced oscillator IVP',r'Solve \(y\prime\prime+4y=\cos t\), y(0)=0, y′(0)=0.',['The forcing frequency is not the natural frequency 2.'],[r'Try A cos t: 3A=1, so yₚ=cos t/3.',r'\(y=C\cos2t+D\sin2t+\cos t/3\). Data give C=−1/3, D=0.'],r'y=\frac{\cos t-\cos2t}{3}','Both initial conditions vanish; the forcing amplitude is reproduced.')
section('3.1.2','Damped oscillations',95,['Classify damping','Use initial values and response amplitude'],r'\gamma^2-4mk\begin{cases}>0&\text{overdamped}\\=0&\text{critical}\\<0&\text{underdamped}\end{cases}','Damping classification depends on the discriminant, not the damping coefficient alone.')
problem('3.1.2','Exercise 3.1.7(a)',99,'Critical damping IVP',r'Solve \(y\prime\prime+2y\prime+y=0\), y(0)=0, y′(0)=1.',['There is a double root at −1.'],[r'\(y=(A+Bt)e^{-t}\).',r'y(0)=A=0; y′(0)=B−A=1.'],r'y=te^{-t}','The repeated root requires the te⁻ᵗ term.')
problem('3.1.2','Exercise 3.1.10(a,b,c)',100,'Compare damping regimes',r'Classify (m,γ,k)=(20,40,100), (25,50,25), (10,50,60), and give general solutions.',['Compute γ²−4mk for each set.'],[r'First discriminant: −6400; roots −1±2i.',r'Second: 0; double root −1.',r'Third: 100; roots −2 and −3.'],r'\begin{aligned}y_a&=e^{-t}(A\cos2t+B\sin2t)\quad\text{underdamped}\\y_b&=(A+Bt)e^{-t}\quad\text{critical}\\y_c&=Ae^{-2t}+Be^{-3t}\quad\text{overdamped}\end{aligned}','Each pair of roots solves mr²+γr+k=0.')
problem('3.1.2','Exercise 3.1.12',100,'Tune a suspension',r'For mass 1500 kg and spring constant 40000 N/m, find the units and value of critical damping γ.',['Set γ²=4mk.'],[r'Since γy′ is a force, γ has units N·s/m.',r'\(\gamma_c=2\sqrt{1500\cdot40000}\).'],r'\gamma_c\approx15491.9\ \mathrm{N\,s/m}','The source prints Ns/m for k; a spring constant must have units N/m. This solution uses the physically consistent units.')
section('3.2','RC and RLC circuits',104,['Write charge and current equations','Use complex amplitudes for sinusoidal forcing'],r'LQ\prime\prime+RQ\prime+Q/C=E(t),\quad I=Q\prime','Charge Q and current I are different variables; I is the time derivative of Q.')
problem('3.2','Supplemental • based on §3.2',104,'Charge an RC circuit',r'R=2 Ω, C=0.5 F, E=10 V, Q(0)=0. Find Q(t) and I(t).',['Use RQ′+Q/C=E.'],[r'The equation is 2Q′+2Q=10, or Q′+Q=5.',r'An integrating factor yields Q=5+Ae⁻ᵗ; A=−5.',r'Differentiate charge to obtain current.'],r'Q=5(1-e^{-t})\ \mathrm C,\quad I=5e^{-t}\ \mathrm A','The final charge is CE=5 C; initial current E/R=5 A.')
problem('3.2','Supplemental • phasor practice',105,'RLC steady response',r'Find steady-state charge for L=1, R=2, C=1, E(t)=cos(2t).',['Use Qₚ=Re(Ae²ⁱᵗ).'],[r'The complex impedance for charge is −4+4i+1=−3+4i.',r'\(A=1/(-3+4i)=(-3-4i)/25\). Take the real part after multiplying by e²ⁱᵗ.'],r'Q_p=-\frac3{25}\cos2t+\frac4{25}\sin2t','Substitution in Q″+2Q′+Q gives cos(2t). Transients decay separately.')
section('8.2','Linear algebra toolkit',179,['Compute determinants and inverses','Solve systems and find eigenpairs'],r'\det(A-\lambda I)=0,\qquad(A-\lambda I)v=0','Eigenvectors must be nonzero; a singular matrix has no inverse.')
problem('8.2','Exercise 8.2.3(b) & 8.2.4(b)',190,'Determinant and inverse',r'Find det A and A⁻¹ for \(A=\begin{pmatrix}2&5\\5&-4\end{pmatrix}\).',['Use ad−bc and the 2×2 inverse formula.'],[r'\(\det A=2(-4)-25=-33\).',r'Swap the diagonal entries, negate off-diagonals, divide by −33.'],r'A^{-1}=\frac1{33}\begin{pmatrix}4&5\\5&-2\end{pmatrix}','Multiplying A by this inverse gives the identity.')
problem('8.2','Exercise 8.2.5(a)',191,'Solve a linear system',r'Solve \(x_1+2x_2=4\), \(2x_1-x_2=3\).',['Eliminate x₁ by subtracting twice the first equation from the second.'],[r'The elimination gives −5x₂=−5, hence x₂=1.',r'Substitute into the first equation to get x₁=2.'],r'(x_1,x_2)=(2,1)','Both equations evaluate to their stated right sides.')
problem('8.2','Exercise 8.2.6(a) & 8.2.7(a)',191,'Eigenvalues and eigenvectors',r'Find eigenpairs of \(A=\begin{pmatrix}3&2\\2&3\end{pmatrix}\).',['Symmetric and antisymmetric vectors are useful.'],[r'\(\det(A-\lambda I)=(3-\lambda)^2-4=(\lambda-5)(\lambda-1)\).',r'For λ=5 use (1,1); for λ=1 use (1,−1).'],r'\lambda_1=5,\ v_1=(1,1)^T;\quad\lambda_2=1,\ v_2=(1,-1)^T','A(1,1)ᵀ=5(1,1)ᵀ and A(1,−1)ᵀ=(1,−1)ᵀ.')
problem('8.2','Exercise 8.2.6(c) & 8.2.7(c)',191,'Complex eigenpairs',r'Find eigenpairs of \(A=\begin{pmatrix}0&1\\-1&0\end{pmatrix}\).',['The characteristic polynomial is λ²+1.'],[r'Roots are i and −i.',r'For λ=i take v=(1,i)ᵀ. For λ=−i take v=(1,−i)ᵀ.'],r'\lambda=\pm i,\qquad v=(1,\pm i)^T','The conjugate eigenpairs correspond to rotation in real coordinates.')
section('4.1-4.2','Systems: formulation and uniqueness',111,['Convert higher-order equations to first-order systems','Use a fundamental matrix'],r'\mathbf x\prime=A(t)\mathbf x+\mathbf f(t)','The state must include enough derivatives to reconstruct the original equation.')
problem('4.1-4.2','Supplemental • §§4.1–4.2',113,'Convert and check uniqueness',r'Write \(y\prime\prime+3y\prime+2y=\sin t\), y(0)=1, y′(0)=0 as a first-order IVP. Is it uniquely solvable?',['Let x₁=y and x₂=y′.'],[r'\(x_1\prime=x_2\), \(x_2\prime=-2x_1-3x_2+\sin t\).',r'The coefficients and forcing are continuous for all real t, so the linear IVP has a unique global solution.'],r'\mathbf x\prime=\begin{pmatrix}0&1\\-2&-3\end{pmatrix}\mathbf x+\binom0{\sin t},\quad\mathbf x(0)=\binom10','Recover y″ by differentiating x₁′=x₂.')
section('4.3','Variation of parameters for systems',116,['Construct a fundamental matrix','Integrate the transformed forcing'],r'\mathbf x=\Phi(t)\left[\mathbf c+\int\Phi^{-1}(t)\mathbf f(t)dt\right]','Matrix multiplication order matters.')
problem('4.3','Supplemental • based on §4.3',116,'Diagonal forced system',r'Solve x′=diag(1,−1)x+(eᵗ,1)ᵀ with x(0)=(0,0)ᵀ.',['Use Φ=diag(eᵗ,e⁻ᵗ) and integrate from 0 to t.'],[r'\(\Phi^{-1}f=(1,e^t)^T\).',r'The integral from 0 to t is (t,eᵗ−1)ᵀ.',r'Multiply by Φ.'],r'\mathbf x(t)=\binom{te^t}{1-e^{-t}}','x₁′=x₁+eᵗ and x₂′=−x₂+1; initial vector is zero.')
section('4.4','Constant-coefficient systems',118,['Diagonalize when possible','Use Jordan form or matrix exponentials'],r'\mathbf x(t)=e^{tA}\mathbf x(0)','A repeated eigenvalue may not have a full eigenvector basis.')
problem('4.4','Exercise 4.5.1(a)',125,'A symmetric system',r'Solve \(v\prime=\begin{pmatrix}4&2\\2&4\end{pmatrix}v\), v(0)=(3,5)ᵀ.',['Use eigenvectors (1,1) and (1,−1).'],[r'Eigenvalues are 6 and 2.',r'\((3,5)^T=4(1,1)^T-(1,-1)^T\).',r'Multiply each component by its exponential.'],r'v=4e^{6t}\binom11-e^{2t}\binom1{-1}','At t=0 the vector is (3,5)ᵀ.')
problem('4.4','Exercise 4.5.1(c)',125,'A defective matrix',r'Solve \(v\prime=\begin{pmatrix}1&2\\0&1\end{pmatrix}v\), v(0)=(2,3)ᵀ.',['Write A=I+N with N²=0.'],[r'\(e^{tA}=e^t(I+tN)=e^t\begin{pmatrix}1&2t\\0&1\end{pmatrix}\).',r'Multiply by (2,3)ᵀ.'],r'v=e^t\binom{2+6t}{3}','The factor t appears because the repeated eigenvalue has a Jordan block.')
problem('4.4','Exercise 4.5.2(c)',125,'A rotation exponential',r'Find \(e^{tA}\) for \(A=\begin{pmatrix}0&1\\-1&0\end{pmatrix}\).',['Use A²=−I and split the exponential series into even and odd powers.'],[r'Even powers sum to I cos t, odd powers to A sin t.'],r'e^{tA}=\begin{pmatrix}\cos t&\sin t\\-\sin t&\cos t\end{pmatrix}','At t=0 it is I and its derivative is A times itself.')
section('5.1-5.2','Boundary values and solvability',129,['Distinguish IVPs from BVPs','Check whether boundary equations are consistent'],r'\text{A linear BVP can have 0, 1, or infinitely many solutions.}','Continuous coefficients do not ensure uniqueness for a BVP.')
problem('5.1-5.2','Supplemental • based on §5.2 examples',131,'Zero, one, or infinitely many',r'For y″+y=0 classify: (a) y(0)=0,y(π)=0; (b) y(0)=0,y(π)=1; (c) y(0)=0,y(π/2)=1.',['Start with A cos x+B sin x.'],[r'All three have A=0 from the left endpoint.',r'(a) gives 0=0, leaving B free. (b) gives 0=1, impossible. (c) gives B=1.'],r'\text{(a) infinitely many }B\sin x;\quad\text{(b) none};\quad\text{(c) }\sin x','Boundary equations, rather than the IVP theorem, determine solvability.')
section('5.3','Eigenvalue boundary problems',134,['Split positive, zero, and negative λ','Include a zero mode for Neumann conditions'],r'y\prime\prime+\lambda y=0','The identically zero function does not count as an eigenfunction.')
problem('5.3','Exercise 5.3.1(a)',138,'Neumann eigenvalues',r'Find all eigenpairs for y″+λy=0, y′(0)=0, y′(5)=0.',['Check λ=0 separately.'],[r'For λ=k²>0, y=A cos kx+B sin kx. The first condition gives B=0 and the second sin(5k)=0.',r'For λ=0, y=A+Bx and B=0, leaving a nonzero constant.',r'For λ<0, hyperbolic solutions and both derivative conditions force the zero function.'],r'\lambda_n=(n\pi/5)^2,\quad y_n=\cos(n\pi x/5),\quad n=0,1,2,\ldots','The n=0 eigenfunction is 1.')
problem('5.3','Exercise 5.3.1(b)',138,'Mixed boundary conditions',r'Find eigenpairs for y″+λy=0, y′(0)=0, y(3)=0.',['Cos(3k)=0 replaces sin(3k)=0.'],[r'For positive λ=k², the left condition removes the sine term.',r'\(\cos3k=0\Rightarrow k=(n+1/2)\pi/3\).',r'λ=0 and λ<0 yield only the zero solution.'],r'\lambda_n=\left(\frac{(n+1/2)\pi}{3}\right)^2,\quad y_n=\cos\left(\frac{(n+1/2)\pi x}{3}\right),\quad n\ge0','There is no constant mode because the right boundary is Dirichlet.')
problem('5.3','Exercise 5.3.1(d)',138,'Remove the first derivative',r'Find eigenpairs of y″+2y′+λy=0, y(0)=0, y(π)=0.',['Set y=e⁻ˣz.'],[r'Substitution gives z″+(λ−1)z=0 with the same zero endpoint conditions.',r'Nontrivial modes have λ−1=n², n≥1.'],r'\lambda_n=1+n^2,\quad y_n=e^{-x}\sin(nx),\quad n=1,2,\ldots','The transformation shifts the eigenvalues by 1.')
section('6.1','Orthogonal expansions',139,['Compute projection coefficients','Use the correct normalization'],r'c_n=\frac{\langle f,\phi_n\rangle}{\langle\phi_n,\phi_n\rangle}','An orthogonal basis need not be normalized.')
problem('6.1','Supplemental • based on §6.1',139,'Project onto two functions',r'On (0,π), project f(x)=1 onto the span of sin x and sin 2x.',['Use the integral inner product; both squared norms are π/2.'],[r'\(\int_0^\pi\sin x\,dx=2\) and \(\int_0^\pi\sin2x\,dx=0\).',r'Divide by π/2 to get coefficients 4/π and 0.'],r'P f=\frac4\pi\sin x','The residual is orthogonal to each of the two basis functions.')
section('6.2','Sturm–Liouville theory',140,['Identify the weight','Use weighted orthogonality'],r'-(p y\prime)\prime+qy=\lambda r y,\quad\langle f,g\rangle_r=\int_a^b fgr\,dx','Use the weight r in both numerator and denominator of coefficient formulas.')
problem('6.2','Supplemental • based on §6.2',140,'Identify a weighted problem',r'Write \((xy\prime)\prime+\lambda xy=0\) on [1,2], y(1)=y(2)=0 in Sturm–Liouville form; identify p,q,r and the inner product.',['Move the derivative term to the opposite side.'],[r'\(-(xy\prime)\prime=\lambda xy\), so p=x, q=0, r=x.',r'Both p and r are positive on [1,2]. Distinct eigenfunctions are orthogonal under weight x.'],r'\langle f,g\rangle_r=\int_1^2 x f(x)g(x)\,dx','The interval avoids the singular endpoint x=0.')
section('6.3','Fourier sine series',141,['Choose the interval length L','Integrate coefficients and interpret endpoint values'],r'B_n=\frac2L\int_0^L f(x)\sin(n\pi x/L)\,dx','A sine expansion is an odd extension; it takes value zero at the endpoints.')
problem('6.3','Exercise 6.7.2(a) • sine part',152,'Sine expansion of a constant',r'Find the Fourier sine series of f(x)=42 on (0,π).',['Integrate sin(nx) between 0 and π.'],[r'\(B_n=(84/\pi)\int_0^\pi\sin(nx)dx=84[1-(-1)^n]/(\pi n)\).',r'Even coefficients vanish and odd coefficients are 168/(πn).'],r'42=\frac{168}{\pi}\sum_{j=0}^{\infty}\frac{\sin((2j+1)x)}{2j+1},\quad0<x<\pi','At x=0 or π the series is 0, consistent with the odd extension’s jump averages.')
problem('6.3','Exercise 6.7.2(c) • sine part',152,'A linear function on (0,3)',r'Find sine coefficients for f(x)=5−2x on (0,3).',['Integrate x sin(nπx/3) by parts.'],[r'Let k=nπ/3. The integral is \([-(5-2x)\cos(kx)/k-2\sin(kx)/k^2]_0^3\).',r'It equals \((5+(-1)^n)/k\). Multiply by 2/3.'],r'B_n=\frac{2(5+(-1)^n)}{n\pi},\quad f(x)=\sum_{n=1}^{\infty}B_n\sin(n\pi x/3)','This represents f in the open interval; the endpoint values of the sine series are 0.')
section('6.4','Fourier cosine series',143,['Keep the constant term convention','Use an even extension'],r'A_0=\frac1L\int_0^L f\,dx,\quad A_n=\frac2L\int_0^L f\cos(n\pi x/L)\,dx','These notes use A₀ as the constant term, not A₀/2.')
problem('6.4','Exercise 6.7.2(a) • cosine part',152,'Cosine expansion of a constant',r'Find the Fourier cosine series of f(x)=42 on (0,π).',['Compute the mean separately.'],[r'\(A_0=\pi^{-1}\int_0^\pi42dx=42\).',r'For n≥1, the integral of cos(nx) is zero, so Aₙ=0.'],r'f(x)=42','The cosine basis already includes the constant function.')
problem('6.4','Exercise 6.7.2(c) • cosine part',152,'Cosine coefficients of a line',r'Find the cosine expansion of f(x)=5−2x on (0,3).',['The mean is 2; use integration by parts for higher coefficients.'],[r'\(A_0=(1/3)\int_0^3(5-2x)dx=2\).',r'With k=nπ/3, the cosine integral is \(-2[(-1)^n-1]/k^2\). Multiply by 2/3.'],r'f(x)=2+\sum_{n=1}^{\infty}\frac{12(1-(-1)^n)}{n^2\pi^2}\cos(n\pi x/3)','At x=0 the sum is 5; at x=3 it is −1, matching the continuous even extension.')
section('7.1','The heat equation',153,['Separate space and time','Choose sine or cosine modes from boundary conditions'],r'u_t=\sigma u_{xx},\quad T_n=e^{-\sigma(n\pi/L)^2t}','Neumann problems retain the mean; homogeneous Dirichlet problems decay to zero.')
problem('7.1','Supplemental • based on §7.1',157,'Dirichlet heat modes',r'Solve uₜ=2uₓₓ on (0,π), u(0,t)=u(π,t)=0, u(x,0)=3sin x+sin 2x.',['Each sine mode evolves independently.'],[r'For sin(nx), the spatial second derivative is −n² sin(nx).',r'The time equation is T′=−2n²T. Preserve the initial coefficients 3 and 1.'],r'u=3e^{-2t}\sin x+e^{-8t}\sin2x','At t=0 the initial profile is recovered; each mode satisfies the PDE and boundary conditions.')
problem('7.1','Supplemental • based on §7.1.3',161,'Insulated endpoints',r'Solve uₜ=uₓₓ on (0,π), uₓ(0,t)=uₓ(π,t)=0, u(x,0)=2+cos x.',['Use the constant mode and a cosine mode.'],[r'The constant mode has eigenvalue 0 and stays fixed.',r'The cos x mode has eigenvalue 1 and decays as e⁻ᵗ.'],r'u=2+e^{-t}\cos x,\quad\lim_{t\to\infty}u=2','The preserved average is 2; the derivative at both endpoints is zero.')
section('7.2','The wave equation',162,['Use both initial displacement and velocity','Divide velocity coefficients by modal frequency'],r'u_{tt}=c^2u_{xx},\quad\omega_n=cn\pi/L','The sine-in-time coefficient is the velocity coefficient divided by ωₙ.')
problem('7.2','Exercise 7.2.1(a)',166,'Wave equation with a linear profile',r'Solve uₜₜ=9uₓₓ on (0,2), u(0,t)=u(2,t)=0, u(x,0)=x, uₜ(x,0)=0.',['Here c=3, L=2; expand x in a sine series.'],[r'\(B_n=\int_0^2x\sin(n\pi x/2)dx=4(-1)^{n+1}/(n\pi)\).',r'Zero initial velocity sets all sine-in-time coefficients to zero.',r'Attach cos(3nπt/2) to each spatial mode.'],r'u=\sum_{n=1}^{\infty}\frac{4(-1)^{n+1}}{n\pi}\sin(n\pi x/2)\cos(3n\pi t/2)','The initial profile is recovered for 0<x<2. It disagrees with the right endpoint boundary, so the data do not define a continuous classical solution at that corner; use the Fourier/weak interpretation.')
section('7.3','Laplace’s equation',166,['Solve a rectangular boundary problem','Normalize hyperbolic factors at the forced edge'],r'u_{xx}+u_{yy}=0','One coordinate has oscillatory modes; the other has hyperbolic modes.')
problem('7.3','Supplemental • based on §7.3',167,'One nonzero edge',r'On 0<x<π, 0<y<1 solve Δu=0 with u(0,y)=u(π,y)=u(x,0)=0 and u(x,1)=sin(2x).',['Choose X=sin(2x); then Y″−4Y=0.'],[r'The bottom boundary removes the cosh term, so Y=B sinh(2y).',r'The top boundary gives B=1/sinh 2.'],r'u(x,y)=\sin(2x)\frac{\sinh(2y)}{\sinh2}','uₓₓ=−4u and uᵧᵧ=4u; all four edges match.')

schedule=Path(r'C:/Users/kunal/Downloads/Calendar Fa2026.txt').read_text()
lectures=[]
for date,num,key in re.findall(r'(\d\d-\d\d): Lecture (\d+), Section ([^\n\r,]+)',schedule):
    key=key.strip()
    if key=='Laplace eq': key='7.3'
    group='m1' if key.startswith('1.') else 'm2' if key.startswith(('2.','3.')) else 'm3' if key.startswith(('4.','5.','6.')) else 'toolkit' if key=='8.2' else 'pde' if key.startswith('7.') else 'tbd'
    lectures.append(dict(number=int(num),date='2026-'+date,section=key,group=group))
for key,s in sections.items():
    prefixes=key.split('-')
    s['sourceExercises']=[dict(ref=ref,page=page) for ref,page in exercises.items() if any(ref.startswith(p+'.') for p in prefixes)]
    if key in ('2.5','2.6'): s['sourceExercises']=[dict(ref=ref,page=page) for ref,page in exercises.items() if ref.startswith('2.6.')]
    if key in ('3.1.1','3.1.2'): s['sourceExercises']=[dict(ref=ref,page=page) for ref,page in exercises.items() if ref.startswith('3.1.')]
    if key=='4.4': s['sourceExercises']=[dict(ref=ref,page=page) for ref,page in exercises.items() if ref.startswith('4.5.')]
    if key in ('6.3','6.4'): s['sourceExercises']=[dict(ref=ref,page=page) for ref,page in exercises.items() if ref.startswith('6.7.')]
data=dict(sections=sections,lectures=lectures,exerciseIndex=exercises,exams=[dict(id='m1',title='Midterm 1',date='2026-09-25',scope='Chapter 1',keys=[k for k in sections if k.startswith('1.')]),dict(id='m2',title='Midterm 2',date='2026-10-23',scope='Chapters 2–3',keys=[k for k in sections if k.startswith(('2.','3.'))]),dict(id='m3',title='Midterm 3',date='2026-12-04',scope='Chapters 4–6',keys=[k for k in sections if k.startswith(('4.','5.','6.'))])])
(out/'content.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'{len(lectures)} lectures; {len(sections)} sections; {sum(len(s["problems"]) for s in sections.values())} worked problems; {len(exercises)} indexed exercise sets')
